interface CorefPair {
  /** 缺失的实体 key（来自 missing_keys） */
  key: string;
  /** 窗口/语料中是否找到了含该实体名的句子 */
  found: boolean;
  /** 找到的句子（必须是窗口/语料原文逐字子串，禁改写） */
  quote?: string;
  /** 引文所在语料绝对行号（window_lines 前缀 L 数字） */
  line_abs?: number;
  /** true=引文取自给定窗口之外（更宽的同章范围），需主会话对语料后核 */
  extended?: boolean;
}
interface RecordResult {
  record_id: string;
  /** 每个缺失 key 一条 pair；真找不到时 found=false 并给 reason */
  pairs: CorefPair[];
  reason?: string;
}
interface BatchResult {
  batch: number;
  results: RecordResult[];
}
interface BatchRecord {
  record_id: string;
  library: string;
  chapter: number;
  missing_keys: string[];
  canonical: Record<string, unknown>;
  window_lines: string[];
}
interface BatchStat {
  batch: number;
  records: number;
  keysFound: number;
  keysVerified: number;
  keysExtended: number;
  keysFailed: number;
}

function normText(s: string): string {
  return s.replace(/[『』「」\[\]（）()…—、，。？！：；\s·～～]/g, "");
}

phase("逐批消解并核验引文");

const paths = await files.glob("迷深实战-工作区/coref_batches/batch-*.json");
log(`共 ${paths.length} 个批次待消解`);

artifact.table("progress", {
  title: "核指消解进度（按批）",
  columns: [
    { field: "batch", label: "批次" },
    { field: "records", label: "件数" },
    { field: "keysFound", label: "找到引文" },
    { field: "keysVerified", label: "核验通过" },
    { field: "keysExtended", label: "窗口外(待后核)" },
    { field: "keysFailed", label: "未消解" },
  ],
  key: "batch",
});

const stats: BatchStat[] = [];
const failures: { batch: number; record_id: string; keys: string[] }[] = [];

const all = await Promise.all(
  paths.map(async (batchPath, i) => {
    const batchNo = i + 1;
    const nn = String(batchNo).padStart(2, "0");
    const batchRaw = await files.read(batchPath);
    const records = JSON.parse(batchRaw) as BatchRecord[];
    const resultsPath = `迷深实战-工作区/coref_batches/results/batch-${nn}.json`;
    const corpus = "语料分析/corpus/clean_full.txt";

    const ask0 =
      `你是中文叙事指代消解专员。读取批文件 ${batchPath}（JSON 数组，每件含 record_id/library/` +
      `missing_keys/canonical/window_lines——window_lines 是原文行，前缀 L<绝对行号>: ）。\n` +
      `任务：对每件的每个 missing_key，在 window_lines 中找一句**逐字包含该实体名或其变体**` +
      `（姓氏省略/仅名/称号/简繁差异）的原文句子。\n` +
      `窗口找不到时，可用 Bash 在语料 ${corpus} 的同章更宽范围找` +
      `（sed -n '<起>,<止>p' 逐段搜，行号参考 window_lines 前缀），此时 extended=true 并附 raw_line。` +
      `若全章确无该实体名，found=false 如实登记——找不到是有效结论，禁止编造引文。\n` +
      `把 BatchResult JSON 写入 ${resultsPath}，并按同一内容作为返回值返回。` +
      ` 若任务不可行或批文件缺失，escalate 说明，不要绕过。`;

    let res = await agent(`消解员-${nn}`).ask<BatchResult>(ask0);

    const verify = (r: BatchResult): { ok: number; ext: number; failed: string[] } => {
      let ok = 0, ext = 0;
      const failed: string[] = [];
      for (const rr of r.results) {
        const rec = records.find((x) => x.record_id === rr.record_id);
        if (!rec) { failed.push(rr.record_id); continue; }
        for (const p of rr.pairs) {
          if (!p.found || !p.quote) { failed.push(rr.record_id); continue; }
          if (p.extended) { ext += 1; ok += 1; continue; }
          const lines = p.line_abs
            ? rec.window_lines.filter((l) => l.startsWith(`L${p.line_abs}: `))
            : rec.window_lines;
          const hit = lines.some((l) => normText(l).includes(normText(p.quote as string)));
          if (hit) { ok += 1; } else { failed.push(rr.record_id); }
        }
      }
      return { ok, ext, failed };
    };

    let v = verify(res);
    if (v.failed.length > 0) {
      const again = await agent(`消解员-${nn}`).ask<BatchResult>(
        `你返回的 JSON 中以下 record_id 的引文未通过逐字核验（引文不是 window_lines 原文的子串，` +
        `或 missing key 没有给出 pair）：${JSON.stringify(v.failed)}。\n` +
        `逐字修正（引文必须从 window_lines 或语料原文原样复制），或改判 found=false。` +
        `重写 ${resultsPath} 并返回修正后的完整 BatchResult。若实体确不存在，found=false 如实登记。`);
      res = again;
      v = verify(res);
    }

    const keysTotal = records.reduce((a, r) => a + r.missing_keys.length, 0);
    const stat: BatchStat = {
      batch: batchNo,
      records: records.length,
      keysFound: v.ok,
      keysVerified: v.ok - v.ext,
      keysExtended: v.ext,
      keysFailed: v.failed.length,
    };
    stats.push(stat);
    report(stat, "progress");
    if (v.failed.length > 0) {
      report({ batch: batchNo, failed_records: v.failed.slice(0, 20) }, "progress");
      failures.push({ batch: batchNo, record_id: `${v.failed.length} 件`, keys: [`${v.failed.length} 个 key 未过核验`] });
    }
    return stat;
  }),
);

phase("汇总产出消解报告");

const totals = all.reduce(
  (a, s) => ({
    records: a.records + s.records,
    keysFound: a.keysFound + s.keysFound,
    keysVerified: a.keysVerified + s.keysVerified,
    keysExtended: a.keysExtended + s.keysExtended,
    keysFailed: a.keysFailed + s.keysFailed,
  }),
  { records: 0, keysFound: 0, keysVerified: 0, keysExtended: 0, keysFailed: 0 },
);

const md = [
  "# B1 核指消解·全量报告",
  "",
  `批次 ${all.length}，记录 ${totals.records} 件，缺失 key ${totals.keysFound + totals.keysFailed} 个。`,
  "",
  `- 找到引文：${totals.keysFound}（核验通过 ${totals.keysVerified}，窗口外待后核 ${totals.keysExtended}）`,
  `- 未消解：${totals.keysFailed}（真缺证据候选 → 人工队列）`,
  `- 消解率：${totals.keysFound + totals.keysFailed > 0 ? Math.round((totals.keysFound / (totals.keysFound + totals.keysFailed)) * 100) : 0}%`,
  "",
  "## 按批明细",
  "",
  ...stats.map((s) => `- 批 ${s.batch}: ${s.records} 件 / 找到 ${s.keysFound} / 核验 ${s.keysVerified} / 窗口外 ${s.keysExtended} / 未消解 ${s.keysFailed}`),
  "",
  "## 下一步（主会话执行）",
  "",
  "1. extended 引文对语料逐条后核（防编造）；",
  "2. 核验通过的引文写为补充证据-核心指代.jsonl，进 G16d 重审；",
  "3. 未消解件直送人工队列。",
].join("\n");

await artifact.markdown("report", md, {
  title: "B1 核指消解全量报告",
  description: "56 批 560 件缺锚记录的 LLM 先行词消解结果与核验明细",
  primary: true,
});

return {
  conclusion: `核指消解完成：${all.length} 批 ${totals.records} 件，缺失 key ${totals.keysFound + totals.keysFailed} 个中找到引文 ${totals.keysFound} 个（核验通过 ${totals.keysVerified}，窗口外 ${totals.keysExtended} 待后核），未消解 ${totals.keysFailed} 个转人工队列。`,
  findings: failures.map((f) => ({
    where: `coref_batches/批${f.batch}`,
    what: `${f.record_id}：${f.keys.join("；")}`,
    evidence: "脚本逐字核验（含标点归一）未通过",
    status: "verified" as const,
    severity: "low" as const,
  })),
  verified: [
    "每条 found 引文在批窗口原文行做包含核验（脚本内，含标点归一）",
    "每批结果由消解员写入 results/batch-NN.json，可独立复查",
  ],
  notCovered: [
    "extended=true 的窗口外引文尚未对语料原文后核（主会话下一步）",
    "消解语义质量由 G16d 双考官重审终判，不在本工作流内",
  ],
};
